#include <iostream>
#include <vector>
#include <string>
using namespace std;

long long sequences(vector<int>& count) {
    long long total = 0;
    for (int c = 0; c < 26; c++) {
        if (count[c] > 0) {
            count[c]--;
            total += 1 + sequences(count);
            count[c]++;
        }
    }
    return total;
}

int main() {
    string tiles;
    cin >> tiles;

    vector<int> count(26, 0);
    for (char ch : tiles) count[ch - 'a']++;
    cout << sequences(count) << "\n";

    return 0;
}

code.java:
import java.util.*;

public class Main {
    static long sequences(int[] count) {
        long total = 0;
        for (int c = 0; c < 26; c++) {
            if (count[c] > 0) {
                count[c]--;
                total += 1 + sequences(count);
                count[c]++;
            }
        }
        return total;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String tiles = sc.next();

        int[] count = new int[26];
        for (char ch : tiles.toCharArray()) count[ch - 'a']++;
        System.out.println(sequences(count));
    }
}
